import React, { useState, useEffect, useMemo } from 'react';
import { invoke } from '@tauri-apps/api/core';
import { useMemoryStore, getFilteredMemories, getMemoryTypeIcon, getMemoryTypeColor, getMemoryTypeLabel, formatMemoryTime, type MemoryType, type MemoryEntryInput } from '../stores/memoryStore';
import { useChatStore } from '../stores/chatStore';
import { useToastContext } from '../contexts/ToastContext';

interface MemoryPanelProps {
  onClose: () => void;
}

export function MemoryPanel({ onClose }: MemoryPanelProps) {
  const toast = useToastContext();
  const messages = useChatStore((s) => s.messages);

  // Store state
  const {
    memories,
    summary,
    searchQuery,
    typeFilter,
    loading,
    selectedMemory,
    isEditing,
    editingMemory,
    loadMemory,
    searchMemory,
    addMemory,
    deleteMemory,
    updateMemory,
    setSearchQuery,
    setTypeFilter,
    setSelectedMemory,
    startEditing,
    stopEditing,
    clearFilters,
  } = useMemoryStore();

  // Local state for add/edit forms
  const [showAddForm, setShowAddForm] = useState(false);
  const [newName, setNewName] = useState('');
  const [newDescription, setNewDescription] = useState('');
  const [newType, setNewType] = useState<MemoryType>('user');
  const [newContent, setNewContent] = useState('');
  const [newTags, setNewTags] = useState('');
  const [editContent, setEditContent] = useState('');

  // Load memories on mount
  useEffect(() => {
    loadMemory();
  }, [loadMemory]);

  // Initialize edit content when editing starts
  useEffect(() => {
    if (editingMemory) {
      setEditContent(editingMemory.content);
    }
  }, [editingMemory]);

  // Get filtered memories with memoization
  const filteredMemories = useMemo(() => {
    return getFilteredMemories(useMemoryStore.getState());
  }, [memories, searchQuery, typeFilter]);

  // Handle add memory
  const handleAddMemory = async () => {
    if (!newName.trim() || !newContent.trim()) {
      toast.addToast({ type: 'error', message: '名称和内容不能为空' });
      return;
    }

    // Validate name format (kebab-case)
    if (!/^[a-z0-9-]+$/.test(newName.trim())) {
      toast.addToast({ type: 'error', message: '名称只能包含小写字母、数字和连字符' });
      return;
    }

    try {
      const entry: MemoryEntryInput = {
        name: newName.trim(),
        description: newDescription.trim() || newContent.trim().slice(0, 50),
        type: newType,
        content: newContent.trim(),
        tags: newTags.trim() ? newTags.trim().split(',').map(t => t.trim()) : undefined,
      };
      await addMemory(entry);
      toast.addToast({ type: 'success', message: `记忆已添加: ${newName}` });
      // Reset form
      setNewName('');
      setNewDescription('');
      setNewType('user');
      setNewContent('');
      setNewTags('');
      setShowAddForm(false);
    } catch (e) {
      toast.addToast({ type: 'error', message: '添加记忆失败' });
    }
  };

  // Handle delete memory
  const handleDeleteMemory = async (name: string) => {
    if (!confirm(`确定要删除记忆 "${name}" 吗？`)) return;
    try {
      await deleteMemory(name);
      toast.addToast({ type: 'success', message: `记忆已删除: ${name}` });
    } catch (e) {
      toast.addToast({ type: 'error', message: '删除记忆失败' });
    }
  };

  // Handle update memory
  const handleUpdateMemory = async () => {
    if (!editingMemory || !editContent.trim()) {
      toast.addToast({ type: 'error', message: '内容不能为空' });
      return;
    }
    try {
      await updateMemory(editingMemory.name, editContent.trim());
      toast.addToast({ type: 'success', message: `记忆已更新: ${editingMemory.name}` });
      stopEditing();
    } catch (e) {
      toast.addToast({ type: 'error', message: '更新记忆失败' });
    }
  };

  // Handle search
  const handleSearch = (query: string) => {
    setSearchQuery(query);
    if (query.trim() !== '') {
      searchMemory(query);
    }
  };

  // Handle extract memory from current conversation
  const handleExtractMemory = async () => {
    try {
      toast.addToast({ type: 'info', message: '正在提取记忆...' });
      const extracted = await invoke('extract_memory', {
        messages: messages.map(m => ({
          role: m.role,
          content: m.content,
          thinking: m.thinking,
          toolName: m.toolName,
        }))
      });

      if (Array.isArray(extracted) && extracted.length > 0) {
        toast.addToast({ type: 'success', message: `成功提取 ${extracted.length} 条记忆` });
        await loadMemory(); // Reload memories
      } else {
        toast.addToast({ type: 'info', message: '未发现新的记忆' });
      }
    } catch (e) {
      console.error('Memory extraction failed:', e);
      toast.addToast({
        type: 'error',
        message: '提取记忆失败: ' + (e instanceof Error ? e.message : '未知错误')
      });
    }
  };

  // Render memory card
  const renderMemoryCard = (memory: typeof memories[0]) => {
    const isSelected = selectedMemory?.name === memory.name;
    const typeIcon = getMemoryTypeIcon(memory.type);
    const typeColor = getMemoryTypeColor(memory.type);

    return (
      <button
        key={memory.name}
        onClick={() => setSelectedMemory(memory)}
        className={`w-full p-3 rounded-lg border transition-all ${
          isSelected
            ? 'border-primary bg-primary/10'
            : 'border-border hover:border-primary/50 hover:bg-accent/30'
        }`}
        aria-label={`记忆: ${memory.name}`}
      >
        <div className="flex items-start gap-3">
          {/* Type icon */}
          <span className={`text-lg ${typeColor}`} aria-hidden="true">
            {typeIcon}
          </span>

          {/* Memory info */}
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              <span className="font-medium text-sm truncate">
                {memory.name}
              </span>
              <span className={`text-xs px-1.5 py-0.5 rounded ${typeColor} bg-opacity-20`}>
                {getMemoryTypeLabel(memory.type)}
              </span>
            </div>
            <p className="text-xs text-muted-foreground mt-1 line-clamp-2">
              {memory.description}
            </p>
            <div className="flex items-center gap-2 mt-1 text-xs text-muted-foreground">
              <span>{formatMemoryTime(memory.metadata.updatedAt)}</span>
              {memory.metadata.tags && memory.metadata.tags.length > 0 && (
                <span className="flex gap-1">
                  {memory.metadata.tags.slice(0, 2).map((tag, idx) => (
                    <span key={idx} className="px-1 bg-muted rounded">
                      {tag}
                    </span>
                  ))}
                </span>
              )}
            </div>
          </div>

          {/* Actions */}
          <div className="flex gap-1">
            <button
              onClick={(e) => {
                e.stopPropagation();
                startEditing(memory);
              }}
              className="text-xs px-1.5 py-0.5 hover:bg-accent rounded transition-colors"
              aria-label={`编辑: ${memory.name}`}
            >
              编辑
            </button>
            <button
              onClick={(e) => {
                e.stopPropagation();
                handleDeleteMemory(memory.name);
              }}
              className="text-xs px-1.5 py-0.5 hover:bg-destructive hover:text-destructive-foreground rounded transition-colors"
              aria-label={`删除: ${memory.name}`}
            >
              删除
            </button>
          </div>
        </div>
      </button>
    );
  };

  return (
    <div
      className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="memory-panel-title"
    >
      <div className="bg-card border shadow-lg rounded-lg max-w-3xl w-full max-h-[85vh] overflow-hidden flex flex-col">
        {/* Header */}
        <div className="p-4 border-b bg-muted/30">
          <div className="flex items-center justify-between">
            <h3 id="memory-panel-title" className="text-lg font-semibold flex items-center gap-2">
              <span aria-hidden="true">🧠</span>
              <span>记忆管理</span>
            </h3>
            <button
              onClick={onClose}
              className="text-muted-foreground hover:text-foreground p-1 rounded hover:bg-accent transition-colors"
              aria-label="关闭"
            >
              ✕
            </button>
          </div>
          {summary && (
            <p className="text-sm text-muted-foreground mt-1">
              共 {summary.totalEntries} 条记忆
              {summary.summaryText && ` - ${summary.summaryText}`}
            </p>
          )}
        </div>

        {/* Search and Filters */}
        <div className="p-3 border-b flex flex-wrap gap-2">
          {/* Search input */}
          <div className="flex-1 min-w-[200px] relative">
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => handleSearch(e.target.value)}
              placeholder="搜索记忆名称、描述、内容..."
              className="w-full px-3 py-1.5 bg-background border rounded text-sm focus:outline-none focus:ring-2 focus:ring-primary"
              aria-label="搜索记忆"
            />
            {searchQuery && (
              <button
                onClick={() => handleSearch('')}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-muted-foreground hover:text-foreground"
                aria-label="清除搜索"
              >
                ✕
              </button>
            )}
          </div>

          {/* Type filter */}
          <select
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value as MemoryType | 'all')}
            className="px-3 py-1.5 bg-background border rounded text-sm"
            aria-label="按类型筛选"
          >
            <option value="all">全部类型</option>
            <option value="user">👤 用户记忆</option>
            <option value="feedback">📝 反馈记录</option>
            <option value="project">📁 项目信息</option>
            <option value="reference">📚 参考资料</option>
          </select>

          {/* Clear filters */}
          {(searchQuery || typeFilter !== 'all') && (
            <button
              onClick={clearFilters}
              className="px-3 py-1.5 bg-muted rounded text-sm hover:bg-accent transition-colors"
              aria-label="清除筛选"
            >
              清除筛选
            </button>
          )}

          {/* Add button */}
          <button
            onClick={() => setShowAddForm(!showAddForm)}
            className={`px-3 py-1.5 rounded text-sm font-medium transition-colors ${
              showAddForm
                ? 'bg-muted text-muted-foreground'
                : 'bg-primary text-primary-foreground hover:bg-primary/90'
            }`}
            aria-label={showAddForm ? '取消添加' : '添加记忆'}
          >
            {showAddForm ? '取消' : '+ 添加'}
          </button>

          {/* Extract button */}
          <button
            onClick={handleExtractMemory}
            disabled={messages.length === 0}
            className="px-3 py-1.5 bg-secondary text-secondary-foreground rounded text-sm font-medium hover:bg-secondary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            aria-label="从对话提取记忆"
            title="从当前对话自动提取记忆"
          >
            🧪 提取
          </button>
        </div>

        {/* Add memory form */}
        {showAddForm && (
          <div className="p-4 border-b bg-muted/20 animate-slide-in-up">
            <div className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <input
                  type="text"
                  value={newName}
                  onChange={(e) => setNewName(e.target.value)}
                  placeholder="名称 (kebab-case 格式)"
                  className="px-3 py-1.5 bg-background border rounded text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                  aria-label="记忆名称"
                />
                <select
                  value={newType}
                  onChange={(e) => setNewType(e.target.value as MemoryType)}
                  className="px-3 py-1.5 bg-background border rounded text-sm"
                  aria-label="记忆类型"
                >
                  <option value="user">👤 用户记忆</option>
                  <option value="feedback">📝 反馈记录</option>
                  <option value="project">📁 项目信息</option>
                  <option value="reference">📚 参考资料</option>
                </select>
              </div>
              <input
                type="text"
                value={newDescription}
                onChange={(e) => setNewDescription(e.target.value)}
                placeholder="描述 (简短摘要，可选)"
                className="w-full px-3 py-1.5 bg-background border rounded text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                aria-label="记忆描述"
              />
              <textarea
                value={newContent}
                onChange={(e) => setNewContent(e.target.value)}
                placeholder="内容 (Markdown 格式)"
                rows={4}
                className="w-full px-3 py-1.5 bg-background border rounded text-sm focus:outline-none focus:ring-2 focus:ring-primary resize-none"
                aria-label="记忆内容"
              />
              <input
                type="text"
                value={newTags}
                onChange={(e) => setNewTags(e.target.value)}
                placeholder="标签 (逗号分隔，可选)"
                className="w-full px-3 py-1.5 bg-background border rounded text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                aria-label="记忆标签"
              />
              <div className="flex gap-2">
                <button
                  onClick={handleAddMemory}
                  className="px-4 py-1.5 bg-primary text-primary-foreground rounded text-sm font-medium hover:bg-primary/90 transition-colors"
                  aria-label="保存记忆"
                >
                  保存记忆
                </button>
                <button
                  onClick={() => setShowAddForm(false)}
                  className="px-4 py-1.5 bg-muted text-muted-foreground rounded text-sm hover:bg-muted/80 transition-colors"
                  aria-label="取消添加"
                >
                  取消
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Memory list */}
        <div className="flex-1 overflow-y-auto">
          {loading ? (
            <div className="text-center text-muted-foreground py-8">
              <div className="animate-spin text-2xl mb-2" aria-hidden="true">⏳</div>
              <span className="text-sm">加载记忆...</span>
            </div>
          ) : filteredMemories.length === 0 ? (
            <div className="text-center text-muted-foreground py-8">
              <p className="text-sm">
                {searchQuery || typeFilter !== 'all' ? '未找到匹配的记忆' : '暂无记忆'}
              </p>
              {!searchQuery && typeFilter === 'all' && !showAddForm && (
                <button
                  onClick={() => setShowAddForm(true)}
                  className="mt-2 text-sm text-primary hover:underline"
                  aria-label="添加第一条记忆"
                >
                  添加第一条记忆
                </button>
              )}
            </div>
          ) : (
            <div className="p-3 space-y-2">
              {filteredMemories.map(renderMemoryCard)}
            </div>
          )}
        </div>

        {/* Selected memory detail */}
        {selectedMemory && !isEditing && (
          <div className="p-4 border-t bg-muted/20 animate-slide-in-up max-h-[200px] overflow-y-auto">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-medium">{selectedMemory.name}</span>
              <span className={`text-xs ${getMemoryTypeColor(selectedMemory.type)}`}>
                {getMemoryTypeIcon(selectedMemory.type)} {getMemoryTypeLabel(selectedMemory.type)}
              </span>
            </div>
            <pre className="text-xs bg-background p-2 rounded overflow-auto whitespace-pre-wrap">
              {selectedMemory.content}
            </pre>
            {selectedMemory.metadata.tags && selectedMemory.metadata.tags.length > 0 && (
              <div className="mt-2 flex gap-1">
                {selectedMemory.metadata.tags.map((tag, idx) => (
                  <span key={idx} className="text-xs px-1.5 py-0.5 bg-muted rounded">
                    {tag}
                  </span>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Edit memory form */}
        {isEditing && editingMemory && (
          <div className="p-4 border-t bg-muted/20 animate-slide-in-up">
            <div className="mb-2 flex items-center justify-between">
              <span className="text-sm font-medium">编辑: {editingMemory.name}</span>
              <button
                onClick={stopEditing}
                className="text-xs text-muted-foreground hover:text-foreground"
                aria-label="取消编辑"
              >
                ✕
              </button>
            </div>
            <textarea
              value={editContent}
              onChange={(e) => setEditContent(e.target.value)}
              rows={4}
              className="w-full px-3 py-1.5 bg-background border rounded text-sm focus:outline-none focus:ring-2 focus:ring-primary resize-none"
              aria-label="编辑记忆内容"
            />
            <div className="flex gap-2 mt-2">
              <button
                onClick={handleUpdateMemory}
                className="px-4 py-1.5 bg-primary text-primary-foreground rounded text-sm font-medium hover:bg-primary/90 transition-colors"
                aria-label="保存更改"
              >
                保存更改
              </button>
              <button
                onClick={stopEditing}
                className="px-4 py-1.5 bg-muted text-muted-foreground rounded text-sm hover:bg-muted/80 transition-colors"
                aria-label="取消编辑"
              >
                取消
              </button>
            </div>
          </div>
        )}

        {/* Footer */}
        <div className="p-3 border-t bg-muted/30">
          <div className="flex justify-between items-center text-xs text-muted-foreground">
            <span>
              共 {memories.length} 条记忆
              {filteredMemories.length !== memories.length && ` (显示 ${filteredMemories.length} 条)`}
            </span>
            <span>/memory 快捷命令</span>
          </div>
        </div>
      </div>
    </div>
  );
}